import com.comsol.model.*;import com.comsol.model.util.*;import java.util.*;
public class VerifyCheckpoint {public static void main(String[] a){try{ModelUtil.initStandalone(false);Model m=ModelUtil.load("m",a[0]);String s=ExportNative.savedSolution(m);ExportNative.dataset(m,s);double[] t=m.sol(s).getPVals();System.out.println("TIMES "+t.length+" "+t[0]+" "+t[t.length-1]);m.result().numerical().create("verify","EvalGlobal");m.result().numerical("verify").set("data","dset1");m.result().numerical("verify").set("solnum",new int[]{t.length});String[] ex={"c.intGas(c.rhoCopper)","c.qmetal*1[pC]","c.spatial.relVolMin"};m.result().numerical("verify").set("expr",ex);System.out.println(Arrays.deepToString(m.result().numerical("verify").getReal()));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}}
